export const mutationRequestDigest = (input: MutationRequestAuthority): string =>
  createHash("sha256")
    .update(JSON.stringify({
      kind: input.kind,
      authorityId: input.authorityId,
      authorityGeneration: input.authorityGeneration,
      request: input.request,
    }))
    .digest("hex");

